function parseNumber(val: string | undefined): number {
  if (!val) return 0;
  const clean = val.replace(/["',]/g, '').trim();
  const num = parseFloat(clean);
  return isNaN(num) ? 0 : num;
}

// Split CSV lines supporting quoted characters and custom delimiters
export function parseCSVRow(rowStr: string, delimiter: string = ','): string[] {
  const result: string[] = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < rowStr.length; i++) {
    const char = rowStr[i];
    if (char === '"') {
      if (inQuotes && rowStr[i + 1] === '"') {
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === delimiter && !inQuotes) {
      result.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }
  result.push(current.trim());
  return result;
}

/**
 * แยกชื่อผู้บันทึก (คอลัมน์ ผู้บันทึก) ออกเป็น 2 กรณี:
 * ตัวอย่างข้อมูล: "น.ส.ปวีณา ใยอุ่น / น.ส.ปวีณา ใยอุ่น / น.ส.อุไร  นิกูลรัมย์ / น.ส.อุไร  นิกูลรัมย์"
 * 
 * 1. ถ้ายังไม่มีการบันทึกจ่ายเงิน (ยังไม่ชำระ):
 *    - เอาชื่อแรกสุดเป็น "ผู้บันทึกใบตั้งเบิก" (recordedBy)
 *    - ผู้บันทึกจ่ายเงิน (financeRecordedBy) = undefined
 * 
 * 2. ถ้ามีการบันทึกจ่ายเงิน (ชำระแล้ว):
 *    - เอาชื่อแรกสุดเป็น "ผู้บันทึกใบตั้งเบิก" (recordedBy)
 *    - เอาชื่อสุดท้ายเป็น "ผู้บันทึกจ่ายเงิน" (financeRecordedBy)
 */
export function extractRecordedPersons(
  rawRecordedBy: string,
  isPaid: boolean
): { recordedBy: string; financeRecordedBy?: string } {
  if (!rawRecordedBy || typeof rawRecordedBy !== 'string') {
    return { recordedBy: '' };
  }

  // แยกชื่อด้วยเครื่องหมาย '/' พร้อมตัดช่องว่าง
  const names = rawRecordedBy
    .split('/')
    .map(name => name.trim())
    .filter(name => name.length > 0);

  if (names.length === 0) {
    return { recordedBy: '' };
  }

  const firstPerson = names[0];
  const lastPerson = names[names.length - 1];

  if (!isPaid) {
    // กรณีที่ 1: ยังไม่มีการบันทึกจ่ายเงิน -> เอาชื่อแรกสุดเป็นผู้บันทึกใบตั้งเบิก
    return {
      recordedBy: firstPerson
    };
  }

  // กรณีที่ 2: มีการบันทึกจ่ายเงิน -> เอาชื่อแรกสุดเป็นผู้บันทึกใบตั้งเบิก และชื่อสุดท้ายเป็นผู้บันทึกจ่ายเงิน
  return {
    recordedBy: firstPerson,
    financeRecordedBy: lastPerson
  };
}

export function parseDisbursements(csvText: string): Disbursement[] {
  let cleanText = csvText;
  if (cleanText.charCodeAt(0) === 0xFEFF) {
    cleanText = cleanText.slice(1);
  }

  // Detect delimiter from sample
  const sample = cleanText.slice(0, 1000);
  const tabs = (sample.match(/\t/g) || []).length;
  const commas = (sample.match(/,/g) || []).length;
  const semis = (sample.match(/;/g) || []).length;
  const delimiter = (tabs > commas && tabs > semis) ? '\t' : (semis > commas && semis > tabs ? ';' : ',');

  const lines = cleanText.trim().split(/\r?\n/);
  if (lines.length < 2) return [];

  const disbursements: Disbursement[] = [];

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const cols = parseCSVRow(line, delimiter);

    const rawRecordedBy = cols[0] || '';
    const dbmNo = cols[1] || '';
    const refDocNo = cols[2] || '';
    const company = cols[3] || 'BTC';
    const entryDate = cols[4] || '';
    const dueDate = cols[5] || '';
    const expenseType = cols[6] || '';
    const payeeName = cols[7] || '';
    const payeeBankAccount = cols[8] || '';
    const project = cols[9] || '';
    const paymentMethod = cols[10] || 'โอน';
    const remarks = cols[11] || '';

    // Collect items (up to 10 items)
    const items: { description: string; amount: number }[] = [];
    for (let itemIdx = 0; itemIdx < 10; itemIdx++) {
      const descCol = 12 + itemIdx * 2;
      const amtCol = 13 + itemIdx * 2;
      const desc = cols[descCol] || '';
      const amt = parseNumber(cols[amtCol]);
      if (desc || amt !== 0) {
        items.push({ description: desc, amount: amt });
      }
    }

    const totalAmount = parseNumber(cols[32]);
    const payerAccount = cols[33] || '';
    const chequeNo = cols[34] || '';
    const paymentDate = cols[35] || '';
    const transferAmount = parseNumber(cols[36]);
    const fee = parseNumber(cols[37]);
    const documentLink = cols[38] || '';

    if (!dbmNo && !payeeName && totalAmount === 0 && items.length === 0) {
      continue;
    }

    const isPaid = (paymentDate !== '' && paymentDate !== '-') || transferAmount > 0;
    const isCancelled = refDocNo === 'ยกเลิก' || expenseType === 'ยกเลิก' || dbmNo === 'ยกเลิก';

    // แยกผู้บันทึกตามเงื่อนไข 2 กรณี
    const { recordedBy, financeRecordedBy } = extractRecordedPersons(rawRecordedBy, isPaid);

    disbursements.push({
      id: `dbm-${i}-${dbmNo || Math.random().toString(36).substring(2, 7)}`,
      recordedBy,
      financeRecordedBy,
      dbmNo: dbmNo || `DBM-${i}`,
      refDocNo: refDocNo === '-' ? '' : refDocNo,
      company: company || 'BTC',
      entryDate,
      dueDate: dueDate === '-' ? '' : dueDate,
      expenseType,
      payeeName,
      payeeBankAccount,
      project: project || '(00) บุรีรัมย์',
      paymentMethod,
      remarks,
      items: items.length > 0 ? items : [{ description: expenseType || 'ค่าใช้จ่าย', amount: totalAmount || transferAmount }],
      totalAmount: totalAmount || transferAmount,
      payerAccount: payerAccount === '-' ? '' : payerAccount,
      chequeNo: chequeNo === '-' ? '' : chequeNo,
      paymentDate: paymentDate === '-' ? '' : paymentDate,
      transferAmount: transferAmount || totalAmount,
      fee,
      documentLink: documentLink && documentLink.startsWith('http') ? documentLink : undefined,
      status: isCancelled ? 'cancelled' : (isPaid ? 'paid' : 'pending'),
      isSyncedToLedger: isPaid
    });
  }

  return disbursements;
}

import { compareDisbursementsDesc } from './accounting';

export const INITIAL_DISBURSEMENTS: Disbursement[] = parseDisbursements(RAW_DISBURSEMENT_CSV).sort(compareDisbursementsDesc);
